const P = [[10, 10], [84, 10], [84, 84], [10, 84]];
const names = ['star', 'heart', 'bell', 'gem'];
const cols = [NAVY, NAVY, ACC, NAVY];
const nxt = [1, 2, 3, 0];
for (let i = 0; i < 4; i++) {
  const w = div(`left:${P[i][0]}px;top:${P[i][1]}px;width:56px;height:56px`, vis);
  tile(w, names[i], T.t0 + .05 + i * .08, 'left:0;top:0', {size: 56, bg: '#EEF0F4', color: cols[i], sound: false, float: false});
  const dx = P[nxt[i]][0] - P[i][0];
  const dy = P[nxt[i]][1] - P[i][1];
  mv.slide(w, T.hit, 'translate(0px,0px)', `translate(${dx}px,${dy}px)`);
}
snd('hit', T.hit);
